{
    if seq.len() == 0 {
        // Base case
        assert(seq_to_set_rec(seq) == Set::empty());
        assert(seq.to_set() == Set::empty());
    } else {
        // Recursive case
        let last_elem = seq[seq.len() as int - 1];
        let rest_seq = seq.subrange(0, seq.len() as int - 1);
        
        // Recursively prove for rest
        seq_to_set_equal_rec(rest_seq);
        
        // Prove for full sequence
        assert(seq_to_set_rec(seq) == seq_to_set_rec(rest_seq).insert(last_elem));
        assert(seq.to_set() == rest_seq.to_set().insert(last_elem));
    }
}

